#include "httplib.h"

httplib::Server svr;
svr.Get("/healthz", [&](const httplib::Request &, httplib::Response &res) {
    auto status = registry.check_all(std::chrono::milliseconds(200));
    res.status = status.ok ? 200 : 503;
    res.set_content(status.ok ? "ok" : status.first_failure, "text/plain");
});
svr.listen("0.0.0.0", 8080);
